'use strict';
let splitPreview=null,previewToken=0,previewTimer=null,previewWorker=null,previewJob=null;
function clearSplitPreview(){splitPreview=null;previewToken++;clearTimeout(previewTimer);$('splitResult').textContent='Предпросмотр: —';syncSplitAction()}
function drawSplitPreview(c){if(!splitPreview)return;if(splitPreview.kind==='batch'){let offset=0;for(const part of splitPreview.parts){drawOneSplitPreview(c,part,offset);offset+=part.groups.length}return}drawOneSplitPreview(c,splitPreview,0)}
function drawOneSplitPreview(c,p,offset){if(p.parent?.visible===false)return;let ratio=canvas.width/(canvas.getBoundingClientRect().width||canvas.width),localWidth=canvas.width;const colors=['#dc4f63','#378cc9','#ab6ad0','#3f9f73','#db9133','#747ee4'];c.save();if(p.kind==='layer'){const parent=layers.find(l=>l.id===p.parent.id)||p.parent;const m=layerLinear(parent);c.transform(m.a,m.b,m.c,m.d,parent.x,parent.y);c.translate(-parent.img.width/2,-parent.img.height/2);ratio/=Math.sqrt(Math.abs(m.a*m.d-m.b*m.c));localWidth=parent.img.width}c.drawImage(p.overlay,p.rect.x,p.rect.y);c.lineWidth=1.5*ratio;c.font='bold '+Math.round(12*ratio)+'px system-ui';p.groups.forEach((g,i)=>{const x=p.rect.x+g.x,y=p.rect.y+g.y,color=colors[(i+offset)%colors.length];c.strokeStyle=color;c.strokeRect(x,y,g.w,g.h);const lx=Math.max(0,Math.min(localWidth-28*ratio,x)),ly=Math.max(0,y-21*ratio);c.fillStyle=color;c.fillRect(lx,ly,28*ratio,20*ratio);c.fillStyle='white';c.fillText(String(i+offset+1),lx+6*ratio,ly+14*ratio)});c.restore()}
function acceptPreview(message){const job=previewJob;if(!job||message.token!==previewToken)return;if(message.error){splitPreview=null;$('splitResult').textContent=FragmentErrors.report(message.error,'Не удалось найти объекты.');syncSplitAction();render();return}if(job.kind==='batch'){const parts=message.results.map((result,i)=>makePreview(job.jobs[i],result));splitPreview={kind:'batch',parts,groups:parts.flatMap(p=>p.groups)}}else splitPreview=makePreview(job,message.result);$('splitResult').textContent='Предпросмотр: '+splitPartsLabel(splitPreview.groups.length);syncSplitAction();render()}
function makePreview(job,result){const ids=new Map();result.groups.forEach((g,i)=>g.ids.forEach(id=>ids.set(id,i)));const colors=[[220,79,99],[55,140,201],[171,106,208],[63,159,115],[219,145,51],[116,126,228]],overlay=off(job.rect.w,job.rect.h),c=overlay.getContext('2d'),pixels=c.createImageData(job.rect.w,job.rect.h);for(let p=0;p<result.labels.length;p++){const i=ids.get(result.labels[p]);if(i===undefined)continue;const color=colors[i%colors.length];pixels.data[p*4]=color[0];pixels.data[p*4+1]=color[1];pixels.data[p*4+2]=color[2];pixels.data[p*4+3]=155}c.putImageData(pixels,0,0);return{kind:job.kind,parent:job.parent,rect:job.rect,groups:result.groups,overlay};}
function runPreview(job){previewJob=job;if(typeof Worker!=='undefined')try{if(!previewWorker){previewWorker=new Worker('preview-worker.js?v=release-1317');previewWorker.onmessage=e=>acceptPreview(e.data);previewWorker.onerror=()=>{previewWorker.terminate();previewWorker=null;if(previewJob?.token===previewToken)runPreviewFallback(previewJob)}}previewWorker.postMessage(job.kind==='batch'?{token:job.token,jobs:job.jobs.map(item=>({image:item.image,options:item.options}))}:{token:job.token,image:job.image,options:job.options});return}catch{previewWorker=null}runPreviewFallback(job)}
function runPreviewFallback(job){try{acceptPreview(job.kind==='batch'?{token:job.token,results:job.jobs.map(item=>segmentObjects(item.image,item.options))}:{token:job.token,result:segmentObjects(job.image,job.options)})}catch(e){acceptPreview({token:job.token,error:e.message})}}
function scheduleSplitPreview(){clearTimeout(previewTimer);const token=++previewToken;splitPreview=null;$('splitResult').textContent='Предпросмотр: считаем…';syncSplitAction();render();previewTimer=setTimeout(()=>{if(token!==previewToken)return;try{const source=automaticSource();if(source.rect.w<3||source.rect.h<3)return;runPreview(source.kind==='batch'?{token,kind:'batch',jobs:source.sources.map(item=>({kind:item.kind,parent:item.parent,rect:item.rect,image:automaticInput(item),options:automaticOptions(item)}))}:{token,kind:source.kind,parent:source.parent,rect:source.rect,image:automaticInput(source),options:automaticOptions(source)})}catch(e){$('splitResult').textContent=FragmentErrors.report(e,'Не удалось найти объекты.')}},180)}
